import{_ as t,o as l,c as s,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/suchen-gruppenprozesse/auswahl-filter-i-grundlagen.png",u="/bilder/suchen-gruppenprozesse/auswahl-filter-i-info.png",d="/bilder/suchen-gruppenprozesse/auswahl-filter-i-roter-pfeil.png",h="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-und.png",g="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-oder.png",o="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-ja-nein-weg.png",p="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-not-or.png",c="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-leistungdaten.png",m="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-status.png",f="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-weitere-daten.png",b="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-leistungsdaten.png",v=JSON.parse('{"title":"Filterbedingungen erstellen, testen und speichern","description":"","frontmatter":{"title":"Filterbedingungen erstellen, testen und speichern","source_pageid":1298,"source_revision":4755},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/schuelerfilter-auswahl.md","filePath":"schild3/suchen-gruppenprozesse/schuelerfilter-auswahl.md"}'),w={name:"schild3/suchen-gruppenprozesse/schuelerfilter-auswahl.md"};function k(S,r,z,_,D,E){return l(),s("div",null,[...r[0]||(r[0]=[i('<h1 id="filterbedingungen-erstellen-testen-und-speichern" tabindex="-1">Filterbedingungen erstellen, testen und speichern <a class="header-anchor" href="#filterbedingungen-erstellen-testen-und-speichern" aria-label="Permalink to &quot;Filterbedingungen erstellen, testen und speichern&quot;">​</a></h1><p>Kombinieren Sie Merkmale mehrerer Bereiche im Schülerfilter. Testen Sie die Bedingungen, bevor Sie die Auswahl übernehmen, und speichern Sie wiederkehrende Filter bei Bedarf.</p><h2 id="der-schulerfilter" tabindex="-1">Der Schülerfilter <a class="header-anchor" href="#der-schulerfilter" aria-label="Permalink to &quot;Der Schülerfilter&quot;">​</a></h2><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-grundlagen.png"><img src="'+a+'" alt="Der Schülerfilter erlaubt einfache und komplexe Auswahlkombinationen." loading="lazy"></a></p><p><em>Der Schülerfilter erlaubt einfache und komplexe Auswahlkombinationen.</em></p><p>Mit dem <em>Schülerfilter</em> steht ein sehr mächtiges Werkzeug zur Verfügung, um Schüler in Kombination von vielen Eigenschaften zu finden.</p><p>Rufen Sie ihn über <em>Auswahl</em> auf.</p><p>Es öffnet sich ein Fenster, das an den Kartereiter <em>Schüler</em> erinnert.</p><p>Der Filter hat eine Kopfzeile, hier in Dunkelblau hervorgehoben:</p><ul><li><strong>Filter benennen</strong> wenn sie beabsichtigen, eine zusammengeklickte Filterbedingung zu speichern, geben Sie ihr hier eine Bezeichnung. Wollen Sie nur einmalig Filtern, kann das Feld frei bleiben.</li><li><strong>Testen</strong> führt dazu, dass eine unten zusammengestellte Filterbedingung einmal ausgeführt und getestet wird. Es wird noch nichts im Schülercontainer links verändert. Sind Sie mit der Filterbedingung zufrieden, klicken Sie nach dem <em>Testen</em> auf</li><li><strong>Übernehmen</strong>, um die gefilterten Schüler in den Container links zu übernehmen und mit ihnen weiterarbeiten zu können.</li><li><strong>Speichern</strong> führt dazu, dass ein Filter, dem Sie eine Bezeichnung gegeben haben, über <em>Vorhandende Filterbedingungen laden</em> im Menüband oben wieder aufgerufen werden kann.</li><li><strong>SQL-Befehl in Datei speichern</strong> erlaubt es computeraffinen Nutzern den tatsächlichen Datenbankbefehl in einer Datei abzulegen.</li></ul><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-info.png"><img src="'+u+'" alt="Das Feld Info erläutert die Verwendung des Schülerfilters." loading="lazy"></a></p><p><em>Das Feld Info erläutert die Verwendung des Schülerfilters.</em></p><p>Über <strong>Info</strong> lässt sich eine kurze Bedienungsanleitung zu den Filterbedingungen aufrufen, um Einträge zu negieren, also NICHT nach dem entsprechenden Feldwert zu suchen.</p>',13),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Um Schüler des Jahrgangs 10 zu suchen, die nicht aus dem Ort kommen, würden Sie unten den "),e("em",null,"aktuellen Abschnitt"),n(" wählen, den "),e("em",null,"Jahrgang 10"),n(" aus der Filterliste anklicken. Dann wählen Sie Ihren Schulort und klicken doppelt darauf. Der Ort ist nun "),e("em",null,[e("strong",null,"fett und kursiv")]),n(". Ein Klick auf "),e("em",null,"Testen"),n(" prüft den Filter.")])],-1),i('<p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-roter-pfeil.png" title="Der rote Pfeil."><img src="'+d+'" alt="Der rote Pfeil." loading="lazy"></a></p><p><em>Der rote Pfeil.</em></p><p>Mitunter taucht ein <strong>roter Pfeil</strong> auf. Dieser bedeutet, dass eine Filterbedingung eingestellt wird und mit einem Klick auf den Pfeil wird diese in eine Liste aus optional mehreren Einträgen übernommen.</p><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-und.png"><img src="'+h+'" alt="Ein Beispiel für eine UND-Verknüpfung." loading="lazy"></a></p><p><em>Ein Beispiel für eine UND-Verknüpfung.</em></p><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-oder.png"><img src="'+g+'" alt="Ein Beispiel für eine ODER-Verknüpfung." loading="lazy"></a></p><p><em>Ein Beispiel für eine ODER-Verknüpfung.</em></p><p>Der <em>Schülerfilter</em> stellt über seine Reiter die Daten der entsprechenden Reiter unter <em>Schüler</em> zur Verfügung.</p><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-ja-nein-weg.png"><img src="'+o+'" alt="Filtern bei einem Merkmal auf Ja oder Nein. Über das X wird eine getätigte Einstellung entfernt." loading="lazy"></a></p><p><em>Filtern bei einem Merkmal auf Ja oder Nein. Über das <strong>X</strong> wird eine getätigte Einstellung entfernt.</em></p><p>An vielen Stellen kann eine getätigte Wahl, oft lässt sich bei einem Merkmal <em>Ja</em> oder <em>Nein</em> wählen, mit dem <strong>X</strong> wieder entfernt werden.</p><h3 id="verknupfungen" tabindex="-1">Verknüpfungen <a class="header-anchor" href="#verknupfungen" aria-label="Permalink to &quot;Verknüpfungen&quot;">​</a></h3><p>Standardmäßig nutzt der Filter UND-Verknüpfungen, bei einigen Feldern werden aber auch ODER-Verknüpfungen genutzt.</p><ul><li><strong>UND</strong>: Beide Kriterien müssen zutreffen, damit ein Eintrag angezeigt wird. <strong>Beispiel</strong>: der Schüler ist <em>Volljährig UND Männlich</em>.</li><li><strong>ODER</strong>: Manche Felder werden als ODER-Verknüpfung interpretiert, es reicht also, wenn eines (oder beide) Kriterien zutrifft. LIsten mit Mehrfachauswahl werden also ODER-Verknüpfung interpretiert. <strong>Beispiel</strong>: Eine Person ist aus <em>Beelen ODER Bad Sassendorf ODER Bamberg</em>.</li></ul><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-not-or.png"><img src="'+p+'" alt="Einträge negieren." loading="lazy"></a></p><p><em>Einträge negieren.</em></p><ul><li>Wird ein Wert ausgewählt und Doppelt angeklickt, wird der Eintrag <strong>negiert</strong>. Im Fall dieses Beispiels wurden <em>katholisch ODER evangelisch</em> ausgewählt und negiert, was im Filter alle Personen anzeigt, die WEDER <em>katholisch</em> NOCH <em>evangelisch</em> sind.</li></ul><h3 id="beispiel-leistungsdaten-filtern" tabindex="-1">Beispiel: Leistungsdaten filtern <a class="header-anchor" href="#beispiel-leistungsdaten-filtern" aria-label="Permalink to &quot;Beispiel: Leistungsdaten filtern&quot;">​</a></h3><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-beispiel-leistungdaten.png"><img src="'+c+'" alt="Filtern in den Leistungsdaten auf Schüler der EF, die im Aktuellen Abschnitt Evangelischen Religion als mündlichen Kurs belegt haben." loading="lazy"></a></p><p><em>Filtern in den Leistungsdaten auf Schüler der EF, die im Aktuellen Abschnitt Evangelischen Religion als mündlichen Kurs belegt haben.</em></p><p>Gefiltert werden soll auf alle Schüler, die im aktuellen Schuljahr in der Einführungsphase evangelische Religion als mündlichen Grundkurs belegt haben.</p><p>Die dafür nötigen Einstellungen müssen unter dem Reiter <em>Lernabschnitt/Leistungsdaten</em> getätigt werden</p><p>Wählen Sie den gewünschten Abschnitt und unter <strong>Jahrgang</strong> die <strong>Einführungsphase EF</strong>.</p><p>Wählen Sie unter <strong>Fächer und Noten</strong> das gesuchte <strong>Fach</strong> und die <strong>Kursart</strong>.</p><p>Als verwendete Beziehung muss in diesem Fall UND ausgewählt werden. Die Einstellungen durch einen Klick auf den <strong>roten Pfeil</strong> übernommen.</p>',25),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Für mehrere Fächer oder Kursarten stellen Sie nacheinander die gewünschten Kombinationen ein. Übernehmen Sie jede Kombination mit dem roten Pfeil in die Liste. Unter "),e("strong",null,"Beziehung verwenden"),n(" legen Sie fest, wie die Bedingungen verbunden werden:")]),e("ul",null,[e("li",null,[e("strong",null,"UND:"),n(" Die Schülerinnen und Schüler müssen alle aufgeführten Kombinationen belegt haben.")]),e("li",null,[e("strong",null,"ODER:"),n(" Mindestens eine der aufgeführten Kombinationen muss belegt sein.")])])],-1),i('<h3 id="beispiel-filtern-uber-mehrere-reiter-hinweg" tabindex="-1">Beispiel: Filtern über mehrere Reiter hinweg <a class="header-anchor" href="#beispiel-filtern-uber-mehrere-reiter-hinweg" aria-label="Permalink to &quot;Beispiel: Filtern über mehrere Reiter hinweg&quot;">​</a></h3><p>Gefiltert werden soll nach allen Schülern, die im</p><ul><li>Schuljahr 2021/22</li><li>die Abiturzulassung erhalten,</li><li>das Abitur dann aber nicht bestanden haben und abgegangen sind</li><li>und Englisch als erste Fremdsprache hatten.</li></ul><p>Dafür müssen Einstellungen unter mehreren Reitern getätigt werden:</p><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-status.png"><img src="'+m+'" alt="Individualdaten I: Status." loading="lazy"></a></p><p><em>Individualdaten I: Status.</em></p><ul><li>Wählen Sie unter <strong>Individual-Daten I → Status</strong> nur <strong>Abgänger</strong> aus. Entfernen Sie insbesondere den Haken bei <strong>Aktiv</strong>.</li></ul><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-weitere-daten.png"><img src="'+f+'" alt="Weitere Daten: Sprachenfolge. Tragen Sie das passende Fach ein." loading="lazy"></a></p><p><em>Weitere Daten: Sprachenfolge. Tragen Sie das passende Fach ein.</em></p><ul><li>Öffnen Sie <strong>Weitere Daten</strong> und wählen Sie unter <strong>Sprachenfolge</strong> Englisch als erste Sprache.</li></ul><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-mehrere-reiter-leistungsdaten.png"><img src="'+b+'" alt="Leistungsdaten: Lernabschnitt und Abiturdaten. Die Datenbank ist im Schuljahr 2022/23, es wird hier das Vorherige, 2021/22, gewählt." loading="lazy"></a></p><p><em>Leistungsdaten: Lernabschnitt und Abiturdaten. Die Datenbank ist im Schuljahr 2022/23, es wird hier das Vorherige, 2021/22, gewählt.</em></p><ul><li>Wählen Sie unter <strong>Lernabschnitt/Leistungsdaten</strong> das gewünschte Schuljahr. Das Halbjahr ist für dieses Beispiel nicht entscheidend. Die Abbildung verwendet 2022/23 als aktuelles und 2021/22 als vorheriges Schuljahr; wählen Sie in Ihrer Datenbank die passenden Jahre.</li><li>Ganz unten finden sich die Angaben für die <em>Abiturzulassung</em> und das <em>Bestehen des Abiturs</em>.</li></ul><p>Entfernen Sie hier auch mit dem <strong>X</strong> die Angabe, ob eine Prüfung angesetzt wurde oder nicht. Im Beispiel des Screenshots wird nur gezeigt, wenn zusätzlich auch eine nündliche Prüfung <em>nicht</em> angesetzt war.</p><p><strong>Testen</strong> und <strong>Übernehmen</strong> übernimmt die gefunden Schüler in den Container zur Weiterarbeit.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sch%C3%BClerfilter_(Auswahl)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4755.</p>',17)])])}const B=t(w,[["render",k]]);export{v as __pageData,B as default};
